function api(path,opts){var epoch=authEpoch;opts=opts||{};opts.credentials='include';opts.headers=opts.headers||{};if(opts.body&&typeof opts.body!=='string'&&!(opts.body instanceof FormData)){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(opts.body)}return fetch(API_URL+path,opts).then(async function(r){var result;try{result=await r.json()}catch(e){throw new Error('Некорректный ответ сервера')}if(!r.ok){if(r.status===401&&path!=='/api/login'&&epoch===authEpoch){authToken='';currentUser=null;pendingAttachments=[];replyContext=null;if($('replyPreview'))renderComposerContext();if(state&&state.abort)state.abort.abort();chats=[];activeId=null;localStorage.removeItem('pongy_authenticated');localStorage.removeItem('pongy_cached_user');$('messages').textContent='';$('chatList').textContent='';showAuth()}var error=new Error(result.error||'HTTP '+r.status);error.code=result.code;throw error}return result})}


