function renderMd(text){
text=esc(text);
text=text.replace(/```([\w+-]*)\n?([\s\S]*?)```/g,function(_,l,c){return '<pre>'+c.replace(/^\n/,'')+'</pre>'});
text=text.replace(/`([^`]+)`/g,'<code>$1</code>');
text=text.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
text=text.replace(/\*([^*]+)\*/g,'<em>$1</em>');
text=text.replace(/\[([^\]]+)\]\(([^)]+)\)/g,function(_,label,url){return '<a href="'+esc(safeUrl(url))+'" target="_blank" rel="noopener">'+label+'</a>'});
var lines=text.split('\n'),out=[],ul=false,ol=false;
lines.forEach(function(l){
if(/^\s*[-*]\s+/.test(l)){if(!ul){if(ol){out.push('</ol>');ol=false}out.push('<ul>');ul=true}out.push('<li>'+l.replace(/^\s*[-*]\s+/,'')+'</li>');return}
if(/^\s*\d+\.\s+/.test(l)){if(!ol){if(ul){out.push('</ul>');ul=false}out.push('<ol>');ol=true}out.push('<li>'+l.replace(/^\s*\d+\.\s+/,'')+'</li>');return}
if(ul){out.push('</ul>');ul=false}if(ol){out.push('</ol>');ol=false}
out.push(l);
});
if(ul)out.push('</ul>');if(ol)out.push('</ol>');
return DOMPurify.sanitize(out.join('\n'),{ALLOWED_TAGS:['pre','code','strong','em','a','ul','ol','li','br'],ALLOWED_ATTR:['href','target','rel']});
}

